let gpuVendorHint = '';
let currentBackend = 'wasm';
let currentVendor = '';
let currentDtype = '';
let currentExecutionDevice = 'wasm';
let currentEncoderDtype = 'q8';
let currentDecoderDtype = 'q8';
let currentPipelineSettingsKey = '';
